insert into requests (id, title, type, gov, locality, size, goal, raised, status, urgency, partner, org, corridor, certifying_body, cert_status, source, source_id, source_url, lat, lng, photo, description, timeline_start, timeline_target, schedule, schedule_label, origin_ref, confirmed, beneficiaries, metrics, expert_partner) values (1009, 'Excessive Noise from Modified Vehicles', 'Public Space & Land Use', 'mtlebanon', 'Mansouriye - Mkalless - Daychouniye', null, null, 0, 'proposed', 'High', 'Not yet assigned', 'Mansouriye - Mkalless - Daychouniye — reporting community', null, null, 'pending', 'baladi', '98ee0f1d-356f-4b8f-a5c3-bfb112681b67', 'https://www.baladimap.com/en/issues/98ee0f1d-356f-4b8f-a5c3-bfb112681b67', 33.8583426304096, 35.5679907395089, 'https://nwqypuvekrsuvbypydjb.supabase.co/storage/v1/object/public/issue-photos/illustrations/98ee0f1d-356f-4b8f-a5c3-bfb112681b67-cartoon.png', 'I would like to formally report an ongoing issue concerning excessive noise caused by vehicles with modified exhaust systems in our area. On a daily basis, and particularly during late evening and nighttime hours, several cars are being driven recklessly while producing extremely loud exhaust noises. This disturbance is affecting the peace and quality of life in the neighborhood, especially during hours that are meant for rest. The situation has become increasingly disruptive, with repeated incidents of speeding, aggressive driving, and unnecessary engine revving. This not only creates significant noise pollution but also raises safety concerns for residents. It is important to note that these vehicles belong to residents of the area, and their identity is known to the municipality. Reported on Baladi Map from Mansouriye - Mkalless - Daychouniye, and confirmed by 8 residents. Not yet certified, costed or open for funding.', 'reported 25 Mar', 'TBD — awaiting certification', 'early', 'Not yet certified', 'BM-98EE0F1D', 8, 8, '[{"label":"Residents confirmed","value":8}]'::jsonb, null) on conflict (id) do nothing;
insert into stage_events (request_id, title, shown_date, meta, ref, state, ord) values (1009, 'Reported on Baladi Map', '25 Mar', '8 residents confirmed · not yet certified', 'BM-98EE0F1D', 'pending', 0);
