insert into requests (id, title, type, gov, locality, size, goal, raised, status, urgency, partner, org, corridor, certifying_body, cert_status, source, source_id, source_url, lat, lng, photo, description, timeline_start, timeline_target, schedule, schedule_label, origin_ref, confirmed, beneficiaries, metrics, expert_partner) values (1029, 'Very Poor Internet Infrastructure', 'Public Space & Land Use', 'north', 'Bsarma', null, null, 0, 'proposed', 'High', 'Not yet assigned', 'Bsarma — reporting community', null, null, 'pending', 'baladi', '7775be54-a7f0-4aed-b87f-e2e555e24665', 'https://www.baladimap.com/en/issues/7775be54-a7f0-4aed-b87f-e2e555e24665', 34.3272881368863, 35.8432258206276, null, 'Residents of Bsarma have suffered from very slow and unstable DSL internet for approximately 15 years, with frequent outages, weak speeds, and unreliable connections. This affects students, remote workers, businesses, and families, while nearby areas receive much better service. Despite previous complaints and promises, no effective action has been taken. Although the national network is the government’s responsibility, the municipality can fund and provide a suitable technical room or cabinet and coordinate with the relevant authorities to improve DSL coverage. We request an urgent technical assessment, a clear action plan, and a municipality-funded solution to provide reliable internet to the area. Reported on Baladi Map from Bsarma, and confirmed by 4 residents. Not yet certified, costed or open for funding.', 'reported 1 Aug', 'TBD — awaiting certification', 'early', 'Not yet certified', 'BM-7775BE54', 4, 4, '[{"label":"Residents confirmed","value":4}]'::jsonb, null) on conflict (id) do nothing;
