insert into requests (id, title, type, gov, locality, size, goal, raised, status, urgency, partner, org, corridor, certifying_body, cert_status, source, source_id, source_url, lat, lng, photo, description, timeline_start, timeline_target, schedule, schedule_label, origin_ref, confirmed, beneficiaries, metrics, expert_partner) values (1032, 'Illegal Waste Dumping and Burning in Jadra, Seaside Road', 'Environment & Waste', 'mtlebanon', 'Jadra', null, null, 0, 'proposed', 'High', 'Not yet assigned', 'Jadra — reporting community', null, null, 'pending', 'baladi', '11e8e23d-7728-47fd-8e86-63ae1ec9fc41', 'https://www.baladimap.com/en/issues/11e8e23d-7728-47fd-8e86-63ae1ec9fc41', 33.6390024930445, 35.4021786576497, 'https://nwqypuvekrsuvbypydjb.supabase.co/storage/v1/object/public/issue-photos/40f03d1e-6f72-4f49-8f24-b72d0a573289/1785693013469.jpg?v=1785693028563', 'Large quantities of waste and rubble are being dumped near our residential area, next to the property adjacent to Oras Resort on the seaside road in Jadra, Chouf. The waste is repeatedly burned or bulldozed to make room for new dumping, producing strong foul odors and creating a breeding ground for insects and rodents that threatens public health. We understand the waste is being brought in by people from outside the town, some of whom claim they have permission from Jadra municipality to dump there. We request an inspection and immediate action to stop this. Reported on Baladi Map from Jadra, and confirmed by 5 residents. Not yet certified, costed or open for funding.', 'reported 2 Aug', 'TBD — awaiting certification', 'early', 'Not yet certified', 'BM-11E8E23D', 5, 5, '[{"label":"Residents confirmed","value":5}]'::jsonb, null) on conflict (id) do nothing;
