insert into requests (id, title, type, gov, locality, size, goal, raised, status, urgency, partner, org, corridor, certifying_body, cert_status, source, source_id, source_url, lat, lng, photo, description, timeline_start, timeline_target, schedule, schedule_label, origin_ref, confirmed, beneficiaries, metrics, expert_partner) values (1036, 'Bad Road', 'Public Roads', 'north', 'Tripoli', null, null, 0, 'proposed', 'Medium', 'Not yet assigned', 'Tripoli — reporting community', null, null, 'pending', 'baladi', '9f52b486-21fa-4c88-ab80-3855efcae168', 'https://www.baladimap.com/en/issues/9f52b486-21fa-4c88-ab80-3855efcae168', 34.4234016, 35.843649, 'https://nwqypuvekrsuvbypydjb.supabase.co/storage/v1/object/public/issue-photos/c9ac0788-32f8-437e-8e4c-482804d3ddaa/1782916738110.jpg?v=1782916758218', 'This problem that we face everyday is not only holes in the road but also a garbage and sewage problem.. The situation is infront of a building entrance where the whole road has formed a constant river of dirty water and garbage.. the smell as a result is terrible.. and we cannot enter or exit our building without crossing this dirty river and stepping in disgusting water.. The problem has been for years.. please help us fix this situation.. The holes that are filling with dirty water might not be the main source of the problem but they are helping it become worse.. Unfortunately we can''t detect the main source of the problem.. as there are also messy garbage bins at the top of this dirty road that are severley contributing to this terrible situation, but also it is possible there is a sewage leak that is filling up these holes.. Please help us! Reported on Baladi Map from Tripoli, and confirmed by 6 residents. Not yet certified, costed or open for funding.', 'reported 1 Jul', 'TBD — awaiting certification', 'early', 'Not yet certified', 'BM-9F52B486', 6, 6, '[{"label":"Residents confirmed","value":6}]'::jsonb, null) on conflict (id) do nothing;
