insert into requests (id, title, type, gov, locality, size, goal, raised, status, urgency, partner, org, corridor, certifying_body, cert_status, source, source_id, source_url, lat, lng, photo, description, timeline_start, timeline_target, schedule, schedule_label, origin_ref, confirmed, beneficiaries, metrics, expert_partner) values (1050, 'Ridiculously loud music in baadaran shouf', 'Public Space & Land Use', 'mtlebanon', 'Baadarane', null, null, 0, 'proposed', 'Medium', 'Not yet assigned', 'Baadarane — reporting community', null, null, 'pending', 'baladi', 'c0d86981-5e6e-4da6-afaa-c72ed1f09c97', 'https://www.baladimap.com/en/issues/c0d86981-5e6e-4da6-afaa-c72ed1f09c97', 33.6440453669013, 35.6174826622009, null, 'There is a fairly new restaurant in Baadaran- shouf called fort valley. They blast music all day long at a very high volume. Many families and homes around the village have already called complaining or even visited the restaurant to ask for the volume to be lowered, however to no avail. Worth noting that the village is a very quiet place for people and guests to come and enjoy nature. The actions of Fort Valley are a clear violation of basic principles of good neighbourhood and coexistence and a complete lack of respect towards the village, its culture and its people. We ask for strict rules to be imposed on sound pollution especially in pristine and nature based environments. Reported on Baladi Map from Baadarane, and confirmed by 2 residents. Not yet certified, costed or open for funding.', 'reported 24 Aug', 'TBD — awaiting certification', 'early', 'Not yet certified', 'BM-C0D86981', 2, 2, '[{"label":"Residents confirmed","value":2}]'::jsonb, null) on conflict (id) do nothing;
insert into stage_events (request_id, title, shown_date, meta, ref, state, ord) values (1050, 'Reported on Baladi Map', '24 Aug', '2 residents confirmed · not yet certified', 'BM-C0D86981', 'pending', 0);
