insert into requests (id, title, type, gov, locality, size, goal, raised, status, urgency, partner, org, corridor, certifying_body, cert_status, source, source_id, source_url, lat, lng, photo, description, timeline_start, timeline_target, schedule, schedule_label, origin_ref, confirmed, beneficiaries, metrics, expert_partner) values (1093, 'Bad road', 'Environment & Waste', 'north', 'Tripoli', null, null, 0, 'proposed', 'Medium', 'Not yet assigned', 'Tripoli — reporting community', null, null, 'pending', 'baladi', '087495a8-2098-4373-96a0-44729933131f', 'https://www.baladimap.com/en/issues/087495a8-2098-4373-96a0-44729933131f', 34.4234356, 35.8436567, null, 'This problem that we face everyday is not only holes in the road but also a garbage and sewage problem.. The situation is infront of a building entrance where the whole road has formed a constant river of dirty water and garbage.. the smell as a result is terrible.. and we cannot enter or exit our building without crossing this dirty river and stepping in disgusting water.. The problem has been for years.. please help us fix this situation.. The holes that are filling with dirty water might not be the main source of the problem but they are helping it become worse.. Unfortunately we can''t detect the main source of the problem.. as there are also messy garbage bins at the top of this dirty road that are severley contributing to this terrible situation, but also it is possible there is a sewage leak that is filling up these holes.. Please help us! Reported on Baladi Map from Tripoli, and confirmed by 3 residents. Not yet certified, costed or open for funding.', 'reported 2 Jul', 'TBD — awaiting certification', 'early', 'Not yet certified', 'BM-087495A8', 3, 3, '[{"label":"Residents confirmed","value":3}]'::jsonb, null) on conflict (id) do nothing;
